package com.areadarkener;

/** A scene fade measured with the monotonic clock, independent of frame rate. */
final class DarknessTransition
{
	private static final long DURATION_NANOS = 1_000_000_000L;
	private double start;
	private int target;
	private long startedAt;

	void setTarget(int strength, long now)
	{
		int next = Math.max(0, Math.min(100, strength));
		if (next != target)
		{
			start = valueAt(now);
			target = next;
			startedAt = now;
		}
	}

	double valueAt(long now)
	{
		double progress = Math.max(0, Math.min(1, (double) (now - startedAt) / DURATION_NANOS));
		return start + (target - start) * progress;
	}
}

package com.areadarkener;

final class HslDarkener
{
	private static final int MAX_HSL = 0xFFFF;
	private static final int HSL_HUE_SHIFT = 10;
	private static final int HSL_SATURATION_SHIFT = 7;
	private static final int HSL_HUE_MASK = 0x3F;
	private static final int HSL_SATURATION_MASK = 0x7;
	private static final int HSL_LIGHTNESS_MASK = 0x7F;
	private static final int HSL_HIDDEN_COLOR = 12345678;

	private HslDarkener()
	{
	}

	static int darkenPackedHsl(int packedHsl, int darknessStrength)
	{
		if (packedHsl == HSL_HIDDEN_COLOR || packedHsl < 0 || packedHsl > MAX_HSL)
		{
			return packedHsl;
		}

		int clampedStrength = Math.max(0, Math.min(100, darknessStrength));
		double scale = (100.0 - clampedStrength) / 100.0;
		int hue = (packedHsl >> HSL_HUE_SHIFT) & HSL_HUE_MASK;
		int saturation = (packedHsl >> HSL_SATURATION_SHIFT) & HSL_SATURATION_MASK;
		int lightness = packedHsl & HSL_LIGHTNESS_MASK;
		int newLightness = Math.max(1, Math.min(HSL_LIGHTNESS_MASK, (int) Math.ceil(scale * lightness)));

		return (hue << HSL_HUE_SHIFT) | (saturation << HSL_SATURATION_SHIFT) | newLightness;
	}
}

package com.areadarkener;

import java.util.ArrayList;
import java.util.List;

/** Shared ground edges between tiles resolving to different region IDs. */
final class RegionBoundaries
{
	static List<Edge> find(int[][] regions)
	{
		List<Edge> edges = new ArrayList<>();
		for (int x = 0; x < regions.length; x++)
		{
			for (int y = 0; y < regions[x].length; y++)
			{
				int region = regions[x][y];
				if (region < 0)
				{
					continue;
				}
				if (x + 1 < regions.length && y < regions[x + 1].length
					&& regions[x + 1][y] >= 0 && regions[x + 1][y] != region)
				{
					edges.add(new Edge(x + 1, y, x + 1, y + 1));
				}
				if (y + 1 < regions[x].length && regions[x][y + 1] >= 0 && regions[x][y + 1] != region)
				{
					edges.add(new Edge(x, y + 1, x + 1, y + 1));
				}
			}
		}
		return edges;
	}

	static final class Edge
	{
		final int x1;
		final int y1;
		final int x2;
		final int y2;

		Edge(int x1, int y1, int x2, int y2)
		{
			this.x1 = x1;
			this.y1 = y1;
			this.x2 = x2;
			this.y2 = y2;
		}
	}
}

